import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";

function CategoriesList() {
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);

  const token = localStorage.getItem('token');

  
  useEffect(() => {
    fetchCategories();
  }, []);

  const openCreateModal = () => {
    setEditingCategory({ nom: '' });
    setShowModal(true);
  };

  const handleDelete = async (id) => {
    if (!token) {
      alert('No estás autenticado. Inicia sesión primero.');
      return;
    }
    if (!window.confirm('Segur que vols eliminar aquesta categoria?')) return;
    try {
      const res = await fetch(`http://localhost/api/categories/${id}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
      });

      if (res.status === 401) throw new Error('No autorizado. El token ha caducado o es inválido.');
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error eliminant categoria');
      setCategories(categories.filter(c => c.id !== id));
      alert(data.missatge);
    } catch (err) {
      alert(err.message);
    }
  };

  const openEditModal = (category) => {
    setEditingCategory({ ...category });
    setShowModal(true);
  };

  const handleChange = (e) => {
    setEditingCategory({ ...editingCategory, [e.target.name]: e.target.value });
  };

  const handleSave = async () => {
    if (!token) { alert('No estás autenticado. Inicia sesión primero.'); return; }
    const isEditing = !!editingCategory.id;
    const url = isEditing
      ? `http://localhost/api/categories/${editingCategory.id}`
      : `http://localhost/api/categories`;
    const method = isEditing ? 'PUT' : 'POST';

    try {
      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(editingCategory)
      });
      if (res.status === 401) throw new Error('No autorizado. El token ha caducado o es inválido.');
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || (isEditing ? 'Error actualitzant categoria' : 'Error creant categoria'));
      if (isEditing) setCategories(categories.map(c => c.id === editingCategory.id ? editingCategory : c));
      else setCategories([...(categories || []), data.dada || data]);
      setShowModal(false);
      setEditingCategory(null);
    } catch (err) {
      alert(err.message);
    }
  };

  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  return (
    <div className="mt-4">
      <h2>Llista de Categories</h2>
      <Button variant="primary" className="mb-3" onClick={openCreateModal}>Crear Categoria</Button>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Nom</th>
            <th>Data de Creació</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {categories.length === 0 && (
            <tr><td colSpan="4" className="text-center">No hi ha categories disponibles.</td></tr>
          )}
          {categories.map((category) => (
            <tr key={category.id}>
              <td>{category.id}</td>
              <td>{category.nom}</td>
              <td>{category.created_at ? new Date(category.created_at).toLocaleDateString('ca-ES') : ''}</td>
              <td>
                <Button variant="warning" size="sm" className="me-2" onClick={() => openEditModal(category)}>
                  Editar
                </Button>
                <Button variant="danger" size="sm" onClick={() => handleDelete(category.id)}>
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      {showModal && editingCategory && (
        <div className="modal show d-block" tabIndex="-1">
          <div className="modal-dialog">
            <div className="modal-content">

              <div className="modal-header">
                <h5 className="modal-title">{editingCategory.id ? 'Editar categoria' : 'Crear categoria'}</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowModal(false)}
                />
              </div>

              <div className="modal-body">
                <input
                  className="form-control mb-2"
                  name="nom"
                  value={editingCategory.nom}
                  onChange={handleChange}
                  placeholder="Nom"
                />
              </div>

              <div className="modal-footer">
                <Button variant="secondary" onClick={() => setShowModal(false)}>Cancel·lar</Button>
                <Button variant="success" onClick={handleSave}>{editingCategory.id ? 'Guardar' : 'Crear'}</Button>
              </div>

            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default CategoriesList;
